update models
model_name = #{modelName}, brand = #{brand}, scale = #{scale}, manufacturer = #{manufacturer}, grade = #{grade}, description = #{description}, color = #{color}, limited_edition = #{limitedEdition}, shop_id = #{shopId}, status = #{status}, image = #{image}, price = #{price}, sell_price = #{sellPrice},
where id = #{id}

mapper.select:
select id, model_name, brand, manufacturer, image, price from models


        and brand like concat('%', #{brand}, '%')


        and owner_id = #{ownerId}
